def should_rollback(stable, canary, max_drop=0.02, max_refusal_rate=0.01):
    """stable / canary: accuracy, refusal_rate and cost_per_task measured over the same period."""
    reasons = []
    if canary["accuracy"] < stable["accuracy"] - max_drop:
        reasons.append("accuracy dropped")
    if canary["refusal_rate"] > max(max_refusal_rate, 2 * stable["refusal_rate"]):
        reasons.append("more refusals")
    if canary["cost_per_task"] > 1.5 * stable["cost_per_task"]:
        reasons.append("cost per task +50%")
    return reasons  # empty: continue the rollout; otherwise set CANARY_SHARE = 0.0


print(should_rollback(
    {"accuracy": 0.93, "refusal_rate": 0.002, "cost_per_task": 0.004},
    {"accuracy": 0.90, "refusal_rate": 0.003, "cost_per_task": 0.003},
))  # ['accuracy dropped']
